-- Entraînements : seulement si tous leurs exercices sont validés
update public.trainings t set approved = true where t.id in ('decouverte_detente_sommeil', 'decouverte_etirements_soir', 'decouverte_gainage_express', 'decouverte_meditation', 'decouverte_scan_corporel', 'decouverte_yoga_hanches', 'decouverte_yoga_matin', 'express_abdos', 'express_cardio', 'express_jambes', 'express_pause_bureau', 'express_respiration', 'express_reveil', 'gc_s1_a', 'gc_s1_b', 'gc_s1_c', 'gc_s2_a', 'gc_s2_b', 'gc_s2_c', 'gc_s3_a', 'gc_s3_b', 'gc_s3_c', 'gc_s4_a', 'gc_s4_b', 'gc_s4_c', 'hf_s1_a', 'hf_s1_b', 'hf_s1_c', 'hf_s2_a', 'hf_s2_b', 'hf_s2_c', 'hf_s3_a', 'hf_s3_b', 'hf_s3_c', 'hf_s4_a', 'hf_s4_b', 'hf_s4_c', 'prog_mobilite_s1', 'prog_mobilite_s2', 'prog_mobilite_s3', 'prog_mobilite_s4', 'prog_recup_s1', 'prog_recup_s2', 'prog_recup_s3', 'prog_recup_s4', 'rapide_abdos_1', 'rapide_abdos_2', 'rapide_abdos_3', 'rapide_bras_1', 'rapide_bras_2', 'rapide_bras_3', 'rapide_corps_entier_1', 'rapide_corps_entier_2', 'rapide_corps_entier_3', 'rapide_dos_1', 'rapide_dos_2', 'rapide_dos_3', 'rapide_epaules_1', 'rapide_epaules_2', 'rapide_epaules_3', 'rapide_jambes_1', 'rapide_jambes_2', 'rapide_jambes_3', 'rf_s1_a', 'rf_s1_b', 'rf_s1_c', 'rf_s2_a', 'rf_s2_b', 'rf_s2_c', 'rf_s3_a', 'rf_s3_b', 'rf_s3_c', 'rf_s4_a', 'rf_s4_b', 'rf_s4_c')
  and not exists (select 1 from public.training_items ti join public.exercises e on e.id = ti.exercise_id
                  where ti.training_id = t.id and not e.approved);
-- Programmes : seulement si tous leurs entraînements sont validés
update public.programs p set approved = true where p.id in ('gainage_calisthenie', 'hanches_fessiers', 'remise_en_forme')
  and not exists (select 1 from public.program_days d join public.trainings t on t.id = d.training_id
                  where d.program_id = p.id and not t.approved);

-- Ce qui reste à valider après ce script :
select 'exercices' quoi, count(*) from public.exercises where not approved
union all select 'entraînements', count(*) from public.trainings where not approved
union all select 'programmes', count(*) from public.programs where not approved;
